		_ = v1Repo.Close()
	}
	stop(false)
	if v1Err != nil {
		logging.Debug(ctx, "explain: metadata branch fetch failed; treating as no match",
			slog.String("prefix", prefix),
			slog.String("error", v1Err.Error()))
		return nil, lookup
	}
	fresh, freshErr := newExplainCheckpointLookup(ctx)
	if freshErr != nil {
		logging.Debug(ctx, "explain: lookup rebuild after metadata fetch failed; treating as no match",
			slog.String("prefix", prefix),
			slog.String("error", freshErr.Error()))
		return nil, lookup
	}
	return matchCheckpointPrefix(fresh, prefix), fresh
}"},{"rank":4,"score":38.931,"file_path":"cmd/entire/cli/status.go","start_line":329,"end_line":373,"focus_line":329,"snippet_start_line":329,"snippet_end_line":373,"symbol_start_line":329,"symbol_end_line":373,"language":"Go","kind":"function","symbol_id":"local/cli:Go:cmd/entire/cli/status.go:function:computeCheckpointSyncInfo","symbol_name":"computeCheckpointSyncInfo","qualified_name":"computeCheckpointSyncInfo","signature":"func computeCheckpointSyncInfo(ctx context.Context, s *EntireSettings) checkpointSyncInfo","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func computeCheckpointSyncInfo(ctx context.Context, s *EntireSettings) checkpointSyncInfo {
	elected, err := strategy.ResolveCheckpointSyncRemote(ctx)
