		Remote:   elected.Name,
		Source:   string(elected.Source),
		Unpushed: countUnpushedCheckpointsForStatus(ctx, elected.Name),
	}
}"},{"rank":5,"score":38.931,"file_path":"cmd/entire/cli/strategy/unpushed_checkpoints.go","start_line":21,"end_line":26,"focus_line":21,"snippet_start_line":21,"snippet_end_line":26,"symbol_start_line":21,"symbol_end_line":26,"language":"Go","kind":"function","symbol_id":"local/cli:Go:cmd/entire/cli/strategy/unpushed_checkpoints.go:function:CountUnpushedCheckpoints","symbol_name":"CountUnpushedCheckpoints","qualified_name":"CountUnpushedCheckpoints","signature":"func CountUnpushedCheckpoints(ctx context.Context, remoteName string) (int, error)","signals":["graph:calls","graph:incoming","graph:callers"],"snippet":"func CountUnpushedCheckpoints(ctx context.Context, remoteName string) (int, error) {
