	PreserveAssetsWhenEmpty bool

	// Prompts contains the raw user prompts (replaces existing).
	// See WriteOptions.Prompts.
	Prompts []string

	// Agent identifies the agent type (needed for transcript chunking)
	Agent types.AgentType

package checkpoint

import (
	"context"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// CheckpointReader provides read access to checkpoint-level persistent data.
//
//nolint:revive // CheckpointReader stutter is accepted — the name marks the checkpoint (vs session) read tier.
type CheckpointReader interface {
	Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
	List(ctx context.Context) ([]CheckpointInfo, error)
}

// SessionReader provides read access to session-level data within a checkpoint.
type SessionReader interface {
	ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
	ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error)
	ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error)
	ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error)
}

// PersistentStore provides the production persistent checkpoint storage surface:
// checkpoint-level reads, session-level reads, and the unified Write. Writes go
// through Writer.Write(ctx, WriteRequest); the concrete per-operation methods
// live on the git implementation as the methods Write dispatches to.
type PersistentStore interface {
	CheckpointReader
	SessionReader
	Writer
}

// WriteRequest is a single persistent-store write command. The set is closed to
// other packages: only types in this package can implement it, sealed via the
// unexported isWriteRequest marker. A store dispatches on the concrete type; a
// mirror/fan-out store forwards the same value to each backend's Write.
//
// Four requests are session-level (Session, ReservedSession, SessionTranscript,
// SessionSummary) and one is checkpoint-level (CheckpointAttribution). Adding
// a write operation is a new request type plus one dispatch case in every
// backend. The Store interface stays unchanged, so seam tests must exercise the
// full union because Go does not exhaustively check type switches.
type WriteRequest interface {
	isWriteRequest()
}

// Session creates or replaces a session document within a checkpoint,
// materializing the checkpoint on its first session. (session-level)
type Session WriteOptions

// ReservedSession creates or replaces a session using an ID that was persisted
// before the write began. Its ID kind identifies the backend that minted it, so
// retries remain readable even if the configured primary changed meanwhile.
type ReservedSession WriteOptions

// SessionTranscript replaces a session's transcript, prompts, and skill events
// at stop time without clobbering sibling fields. (session-level)
type SessionTranscript UpdateOptions

// SessionSummary rewrites only the summary of the checkpoint's latest session.
// (session-level)
type SessionSummary struct {
	CheckpointID id.CheckpointID
	Summary      *Summary
}

// CheckpointAttribution rewrites the checkpoint root's combined attribution
// across all sessions. (checkpoint-level)
//
//nolint:revive // CheckpointAttribution stutter is accepted — the name makes the checkpoint (vs session) tier explicit.
type CheckpointAttribution struct {
	CheckpointID id.CheckpointID
	Attribution  *Attribution
}

func (Session) isWriteRequest()               {}
func (ReservedSession) isWriteRequest()       {}
func (SessionTranscript) isWriteRequest()     {}
func (SessionSummary) isWriteRequest()        {}
func (CheckpointAttribution) isWriteRequest() {}

// Writer is the persistent-store write surface: a single Write that accepts any
// WriteRequest. It is the natural type for mirror fan-out.
type Writer interface {
	Write(ctx context.Context, req WriteRequest) error
}

// ReadCheckpoint reads a checkpoint summary and normalizes a nil store response
// into ErrCheckpointNotFound.
func ReadCheckpoint(ctx context.Context, reader CheckpointReader, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	summary, err := reader.Read(ctx, checkpointID)
	if err != nil {
		return nil, fmt.Errorf("read persistent checkpoint: %w", err)
	}
	if summary == nil {
		return nil, ErrCheckpointNotFound
	}
	return summary, nil
}

// ReadLatestSessionContent reads the latest session from an already-resolved
// session reader and summary.
func ReadLatestSessionContent(ctx context.Context, reader SessionReader, checkpointID id.CheckpointID, summary *CheckpointSummary) (*SessionContent, error) {
	if summary == nil || len(summary.Sessions) == 0 {
		return nil, ErrCheckpointNotFound
	}
	latestIndex := len(summary.Sessions) - 1
	content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
	if err != nil {
		return nil, fmt.Errorf("read session %d content: %w", latestIndex, err)
	}
	return content, nil
}

// ReadRawSessionLogForCheckpoint reads a checkpoint's latest-session transcript;
// it needs both reader tiers (resolve the checkpoint, then its latest session).
func ReadRawSessionLogForCheckpoint(ctx context.Context, reader interface {
	CheckpointReader
	SessionReader
}, checkpointID id.CheckpointID) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err //nolint:wrapcheck // Propagating context cancellation
	}

	summary, err := ReadCheckpoint(ctx, reader, checkpointID)
	if err != nil {
		return nil, "", err
	}

	content, err := ReadLatestSessionContent(ctx, reader, checkpointID, summary)
	if err != nil {
		return nil, "", err
	}
	return content.Transcript, content.Metadata.SessionID, nil
}
package checkpoint

import (
	"context"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

var (
	_ PersistentStore = (*GitStore)(nil)
	_ AuthorReader    = (*GitStore)(nil)
	_ Writer          = (*GitStore)(nil)
	_ EphemeralStore  = (*ephemeralStore)(nil)
)

// treeWriter holds the repo-only machinery for building a single checkpoint's
// subtree from write requests: entry builders, transcript/session writers, and
// the per-request appliers (applySessionWrite / applyTranscriptBackfill /
// applySummaryBackfill / applyAttributionBackfill). It is independent of where
// the resulting subtree is committed, so both the git-branch store (which nests
// the subtree under <shard>/<id>/ on the v1 branch) and the git-refs store
// (which keeps it at the root of a per-checkpoint ref) embed it and share this
// code.
type treeWriter struct {
	repo *git.Repository
}

// GitStore is the committed (persistent) checkpoint store. Writes target
// refs.Primary; committed reads resolve against refs.Read. The temporary
// shadow-branch surface lives in ephemeralStore. It embeds *treeWriter for the
// shared subtree-building machinery.
type GitStore struct {
	*treeWriter

	refs                  PersistentRefs
	blobFetcher           BlobFetchFunc
	metadataBranchFetcher MetadataBranchFetchFunc
	// metadataBranchFetchTried latches the one recovery attempt per store; see
	// tryFetchMetadataBranch.
	metadataBranchFetchTried bool
	// readRemotes is the ordered checkpoint read-candidate chain consulted by
	// committed reads after the local tree; see OpenOptions.ReadRemotes. nil
	// means the legacy origin-only fallback.
	readRemotes []string
}

// ephemeralStore is the git shadow-branch (temporary) checkpoint store. It is
// an independent type from GitStore; the two share only package-level helpers.
type ephemeralStore struct {
	repo *git.Repository
	refs PersistentRefs
}

// newEphemeralStore creates the shadow-branch store for the given repository
// and committed-metadata topology (it consults refs.Primary to recognize the
// committed branch when listing shadow branches).
func newEphemeralStore(repo *git.Repository, refs PersistentRefs) *ephemeralStore {
	return &ephemeralStore{repo: repo, refs: refs}
}

// NewEphemeralStore constructs the git shadow-branch (temporary) checkpoint
// store. Most callers reach it via Open(...).Ephemeral(); this direct
// constructor exists for benchmarks and tests that exercise the shadow-branch
// surface without the full facade.
func NewEphemeralStore(repo *git.Repository, refs PersistentRefs) EphemeralStore {
	return newEphemeralStore(repo, refs)
}

// NewGitStore creates a checkpoint store backed by the given git repository
// and committed-metadata topology. Pass DefaultV1Refs() for the v1-only default
// or ResolveRefs(ctx) in code paths that honor settings.
func NewGitStore(repo *git.Repository, refs PersistentRefs) *GitStore {
	return &GitStore{treeWriter: &treeWriter{repo: repo}, refs: refs}
}

// SetBlobFetcher configures the store to automatically fetch missing blobs
// on demand when reading from metadata trees.
func (s *GitStore) SetBlobFetcher(f BlobFetchFunc) {
	s.blobFetcher = f
}

// SetReadRemotes configures the ordered checkpoint read-candidate remotes
// (elected sync remote first, then the legacy origin tier) whose tracking
// refs committed reads consult after the local tree. Selection happens by
// requested checkpoint, so an existing but incomplete tree does not mask a
// later candidate. This is a pure read — the chain never seeds or advances
// local refs. nil keeps the legacy origin-only fallback.
func (s *GitStore) SetReadRemotes(remotes []string) {
	s.readRemotes = remotes
}

// SetMetadataBranchFetcher configures the store to fetch the metadata branch
// from the checkpoint remote when it is missing both locally and on origin.
// See MetadataBranchFetchFunc for when it is appropriate to wire this.
func (s *GitStore) SetMetadataBranchFetcher(f MetadataBranchFetchFunc) {
	s.metadataBranchFetcher = f
}

// Repository returns the underlying git repository.
func (s *GitStore) Repository() *git.Repository {
	return s.repo
}

// Refs returns the committed-metadata topology the store was constructed with.
func (s *GitStore) Refs() PersistentRefs {
	return s.refs
}

// PersistentReadRef returns the ref that committed-checkpoint reads resolve against.
func (s *GitStore) PersistentReadRef() plumbing.ReferenceName {
	return s.refs.Read
}

func (s *GitStore) updatePrimaryRef(ctx context.Context, build func(parentHash, rootTreeHash plumbing.Hash) (plumbing.Hash, error)) error {
	return updatePersistentRef(ctx, s.repo, s.refs.Primary, func() (plumbing.Hash, plumbing.Hash, error) {
		parentHash, rootTreeHash, err := s.getSessionsBranchRef()
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, err
		}
		newHash, buildErr := build(parentHash, rootTreeHash)
		return newHash, parentHash, buildErr
	})
}
