	// ReviewSkills lists the review skills that were run (only set when Kind is a review kind).
	// May be empty when a review was attached post-hoc without declared skills.
	ReviewSkills []string `json:"review_skills,omitempty"`

	// ReviewPrompt is the actual text of the review request (composed prompt
	// for spawn, first user prompt for attach). Only set when Kind is a
	// review kind.
	ReviewPrompt string `json:"review_prompt,omitempty"`

	// InvestigateRunID is the 12-hex-char ID of the parent investigation
	// run. Only set when Kind is an investigate kind.
	InvestigateRunID string `json:"investigate_run_id,omitempty"`

	// InvestigateTopic is the human-readable topic the investigation was
	// asked to investigate. Only set when Kind is an investigate kind.
	InvestigateTopic string `json:"investigate_topic,omitempty"`
}

// GetTranscriptStart returns the transcript line offset at which this checkpoint's data begins.
// Returns 0 for new checkpoints (start from beginning). For data written by older CLI versions,
// falls back to the deprecated TranscriptLinesAtStart field.
func (m Metadata) GetTranscriptStart() int {
	if m.CheckpointTranscriptStart > 0 {
		return m.CheckpointTranscriptStart
	}
	return m.TranscriptLinesAtStart
}

// GetCompactTranscriptStart returns the line offset in transcript.jsonl at which
// this checkpoint's data begins, and whether the offset was recorded. ok=false
// means a legacy checkpoint whose transcript.jsonl holds only this checkpoint's
// delta (read it from line 0); ok=true with offset 0 means the full-compact file
// whose first checkpoint starts at the beginning.
func (m Metadata) GetCompactTranscriptStart() (offset int, ok bool) {
	if m.CompactTranscriptStart == nil {
		return 0, false
	}
	return *m.CompactTranscriptStart, true
}

// SessionFilePaths contains the absolute paths to session files from the git tree root.
// Paths include the full checkpoint path prefix (e.g., "/a1/b2c3d4e5f6/1/metadata.json").
// Used in CheckpointSummary.Sessions to map session IDs to their file locations.
type SessionFilePaths struct {
	Metadata string `json:"metadata"`
	// Transcript points at the raw full.jsonl, which CLI read paths
	// (resume/explain) resolve by filename.
	Transcript string `json:"transcript,omitempty"`
	// CompactTranscript points at the compact transcript.jsonl when one was
	// generated alongside full.jsonl. Omitted otherwise (non-compactable,
	// empty, or oversized transcripts, and older CLI versions). transcript.jsonl
	// holds the full compacted session; this checkpoint's slice begins at the
	// session metadata's compact_transcript_start (see Metadata.CompactTranscriptStart).
	CompactTranscript string `json:"compact_transcript,omitempty"`
	ContentHash       string `json:"content_hash,omitempty"`
	Prompt            string `json:"prompt"`
	// AssetsManifest points at assets/manifest.json when images were externalized
	// out of the transcript into the session's assets/ folder. Omitted otherwise.
	AssetsManifest string `json:"assets_manifest,omitempty"`
}

// CheckpointSummary is the root-level metadata.json for a checkpoint.
// It contains aggregated statistics from all sessions and a map of session IDs
// to their file paths. Session-specific data (including initial_attribution)
// is stored in the session's subdirectory metadata.json.
//
// Structure on entire/checkpoints/v1 branch:
//
//	<checkpoint-id[:2]>/<checkpoint-id[2:]>/
//	├── metadata.json         # This CheckpointSummary
//	├── 1/                    # First session
//	│   ├── metadata.json     # Session-specific Metadata
//	│   ├── full.jsonl        # Raw agent transcript
//	│   ├── transcript.jsonl  # Full compacted session (slice at compact_transcript_start)
//	│   ├── prompt.txt
//	│   └── content_hash.txt
//	├── 2/                    # Second session
//	└── 3/                    # Third session...
//
//nolint:revive // Named CheckpointSummary to avoid conflict with existing Summary struct
type CheckpointSummary struct {
	CLIVersion   string          `json:"cli_version,omitempty"`
	CheckpointID id.CheckpointID `json:"checkpoint_id"`
	Strategy     string          `json:"strategy"`
	Branch       string          `json:"branch,omitempty"`
	// CommitSHA: import-only anchor; see WriteOptions.CommitSHA.
	CommitSHA           string             `json:"commit_sha,omitempty"`
	CheckpointsCount    int                `json:"checkpoints_count"`
	FilesTouched        []string           `json:"files_touched"`
	Sessions            []SessionFilePaths `json:"sessions"`
	TokenUsage          *types.TokenUsage  `json:"token_usage,omitempty"`
	CombinedAttribution *Attribution       `json:"combined_attribution,omitempty"`

	// HasReview is the umbrella "any review happened" flag: true when at least
	// one session in this checkpoint has a review-kind Kind (currently
	// "agent_review"). When new review kinds are introduced they should also
	// cause this flag to be set so callers can keep asking "was this reviewed
	// in any way?" without caring about the variant.
	HasReview bool `json:"has_review,omitempty"`

	// HasInvestigation is the umbrella "any investigation happened" flag:
	// true when at least one session in this checkpoint has an
	// investigate-kind Kind (currently "agent_investigate"). When new
	// investigate kinds are introduced they should also cause this flag to
	// be set so callers can keep asking "was this investigated in any way?"
	// without caring about the variant.
	HasInvestigation bool `json:"has_investigation,omitempty"`

	// Imported is true when this checkpoint was imported from pre-existing
	// agent history (a session with Kind == "imported"): read-only and
	// commit-less.
	Imported bool `json:"imported,omitempty"`
}

// SessionMetrics contains hook-provided session metrics from agents that report
// them via lifecycle hooks (e.g., Cursor). These supplement transcript-derived
// metrics for agents whose transcripts lack usage/timing data.
type SessionMetrics struct {
	DurationMs        int64 `json:"duration_ms,omitempty"`
	TurnCount         int   `json:"turn_count,omitempty"`
	ContextTokens     int   `json:"context_tokens,omitempty"`
	ContextWindowSize int   `json:"context_window_size,omitempty"`
}

// Summary contains AI-generated summary of a checkpoint.
type Summary struct {
	Intent    string           `json:"intent"`     // What user wanted to accomplish
	Outcome   string           `json:"outcome"`    // What was achieved
	Learnings LearningsSummary `json:"learnings"`  // Categorized learnings
	Friction  []string         `json:"friction"`   // Problems/annoyances encountered
	OpenItems []string         `json:"open_items"` // Tech debt, unfinished work
}

// LearningsSummary contains learnings grouped by scope.
type LearningsSummary struct {
	Repo     []string       `json:"repo"`     // Codebase-specific patterns/conventions
	Code     []CodeLearning `json:"code"`     // File/module specific findings
	Workflow []string       `json:"workflow"` // General dev practices
}

// CodeLearning captures a learning tied to a specific code location.
type CodeLearning struct {
	Path    string `json:"path"`               // File path
	Line    int    `json:"line,omitempty"`     // Start line number
	EndLine int    `json:"end_line,omitempty"` // End line for ranges (optional)
	Finding string `json:"finding"`            // What was learned
}

// Attribution captures line-level attribution metrics at commit time.
// This is a point-in-time snapshot comparing the checkpoint tree (agent work)
// against the committed tree (may include human edits).
//
// Attribution Metrics:
//   - TotalCommitted keeps the historical "net additions" view for compatibility
//   - TotalLinesChanged measures total committed line changes (adds + modifies + removes)
//   - AgentPercentage represents "of the lines changed in this commit, what percentage came from the agent"
//   - AgentRemoved tracks committed deletions performed by the agent
type Attribution struct {
	CalculatedAt      time.Time `json:"calculated_at"`
	AgentLines        int       `json:"agent_lines"`              // Lines added by agent that remain in the commit
	AgentRemoved      int       `json:"agent_removed"`            // Lines removed by agent that remain removed in the commit
	HumanAdded        int       `json:"human_added"`              // Lines added by human (excluding modifications)
	HumanModified     int       `json:"human_modified"`           // Lines modified by human (estimate: min(added, removed))
	HumanRemoved      int       `json:"human_removed"`            // Lines removed by human (excluding modifications)
	TotalCommitted    int       `json:"total_committed"`          // Net additions in commit (legacy additions-focused metric)
	TotalLinesChanged int       `json:"total_lines_changed"`      // Total committed line changes (adds + modifies + removes)
	AgentPercentage   float64   `json:"agent_percentage"`         // (agent_lines + agent_removed) / total_lines_changed * 100
	MetricVersion     int       `json:"metric_version,omitempty"` // 0/absent = legacy (additions-only %), 2 = changed-lines %
}
// maintains a CheckpointSummary at the root level with aggregated statistics.
//
// Structure:
//
//	basePath/
//	├── metadata.json         # CheckpointSummary (aggregated stats)
//	├── 1/                    # First session
//	│   ├── metadata.json     # Metadata (session-specific, includes initial_attribution)
//	│   ├── full.jsonl        # Raw agent transcript (CLI resume/explain)
//	│   ├── transcript.jsonl  # Compact transcript scoped to this checkpoint (pushed; not yet referenced by metadata.json)
//	│   ├── prompt.txt
//	│   └── content_hash.txt
//	├── 2/                    # Second session
//	└── ...
func (s *treeWriter) writeStandardCheckpointEntries(ctx context.Context, opts WriteOptions, basePath string, entries map[string]object.TreeEntry) error {
	// Read existing summary to get current session count
	var existingSummary *CheckpointSummary
	metadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
	if entry, exists := entries[metadataPath]; exists {
		existing, err := s.readSummaryFromBlob(entry.Hash)
		if err == nil {
			existingSummary = existing
		} else {
			logging.Debug(ctx, "writeStandardCheckpointEntries: readSummaryFromBlob failed",
				slog.String("metadata_path", metadataPath),
				slog.String("error", err.Error()))
		}
	}

	// Determine session index: reuse existing slot if session ID matches, otherwise append
	sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)

	// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
	// findSessionIndex only returns 0 when existingSummary is nil (fresh write)
	// or when the summary claims slot 0 belongs to us — either way, the tree
	// actually holding session-0 metadata for someone else is a corruption /
	// stale-summary shape. Writing through it would overwrite data we don't
	// know about. Bail instead of silently clobbering.
	//
	// We read and capture BEFORE writeSessionToSubdirectory clears the subtree,
	// otherwise we'd only ever see our own write.
	if sessionIndex == 0 {
		if entry, exists := entries[checkpointSubtreePath(basePath, "0", paths.MetadataFileName)]; exists {
			if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
				logging.Error(ctx, "refusing checkpoint write: session 0 holds a different sessionID",
					slog.String("checkpoint_id", opts.CheckpointID.String()),
					slog.String("existing_session_id", existingMeta.SessionID),
					slog.String("write_session_id", opts.SessionID),
					slog.Bool("existing_summary_nil", existingSummary == nil))
				return fmt.Errorf(
					"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree entire/checkpoints/v1 %s/`",
					opts.CheckpointID, existingMeta.SessionID, opts.SessionID, opts.CheckpointID.Path(),
				)
			}
		}
	}

	// Write session files to numbered subdirectory
	sessionDir := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex))
	sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionDir, entries)
	if err != nil {
		return err
	}

	// Copy additional metadata files from directory if specified (to session subdirectory)
	if opts.MetadataDir != "" {
		if err := s.copyEntireMetadataDir(ctx, opts.MetadataDir, sessionDir, entries); err != nil {
			return fmt.Errorf("failed to copy metadata directory: %w", err)
		}
	}

	// Build the sessions array
	var sessions []SessionFilePaths
	if existingSummary != nil {
		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
		copy(sessions, existingSummary.Sessions)
	} else {
		sessions = make([]SessionFilePaths, 1)
	}
	sessions[sessionIndex] = sessionFilePaths

	// Tripwire: an unreproduced production report had session 0 silently
	// replaced with a different sessionID's data. The symptom was
	// findSessionIndex returning 0 when it should have returned N
	// (append). That happens if existingSummary is nil — yet the
	// on-disk tree clearly had session 0's metadata. If we're writing
	// at sessionIndex=0 while entries has pre-existing session-0
	// metadata with a DIFFERENT sessionID, that's the exact bug shape.
	// Loud WARN so we get a log trace instead of only the symptom.
	if sessionIndex == 0 {
		path := checkpointSubtreePath(basePath, "0", paths.MetadataFileName)
		if entry, exists := entries[path]; exists {
			if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
				logging.Warn(ctx, "checkpoint write overwrites session 0 with a different sessionID — potential overwrite regression",
					slog.String("checkpoint_id", opts.CheckpointID.String()),
					slog.String("existing_session_id", existingMeta.SessionID),
					slog.String("write_session_id", opts.SessionID),
					slog.Bool("existing_summary_nil", existingSummary == nil))
			}
		}
	}

	// Update root metadata.json with CheckpointSummary
	return s.writeCheckpointSummary(opts, basePath, entries, sessions)
}

// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
// Returns the absolute file paths from the git tree root for the sessions map.
func (s *treeWriter) writeSessionToSubdirectory(ctx context.Context, opts WriteOptions, sessionDir string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
	filePaths := SessionFilePaths{}

	// Clear any existing entries under this session dir so stale files from a
	// previous write (e.g. prompt.txt) don't persist on overwrite. Match on the
	// dir plus "/" so a sibling session (e.g. "10") isn't caught by "1".
	for key := range entries {
		if strings.HasPrefix(key, sessionDir+"/") {
			delete(entries, key)
		}
	}

	// Write transcript. Transcript points at full.jsonl (CLI
	// resume/explain read it by filename); the compact transcript.jsonl,
	// when written, is also pushed and pointed at by CompactTranscript.
	wroteTranscript, compactTranscriptStart, err := s.writeTranscript(ctx, opts, sessionDir, entries)
	if err != nil {
		return filePaths, err
	}
	if wroteTranscript {
		filePaths.Transcript = "/" + checkpointSubtreePath(sessionDir, paths.TranscriptFileName)
		filePaths.ContentHash = "/" + checkpointSubtreePath(sessionDir, paths.ContentHashFileName)
		// Point at the compact transcript only when it was actually written
		// (best-effort), deriving from the tree entry so the path can't dangle.
		if _, ok := entries[checkpointSubtreePath(sessionDir, paths.CompactTranscriptFileName)]; ok {
			filePaths.CompactTranscript = "/" + checkpointSubtreePath(sessionDir, paths.CompactTranscriptFileName)
		}
	}

	// Write externalized image assets (raw binary blobs + manifest), when present.
	manifestPath, err := s.writeAssets(opts.Assets, sessionDir, entries)
	if err != nil {
		return filePaths, err
	}
	filePaths.AssetsManifest = manifestPath

	// Write prompts via the regex-only pipeline. OPF runs only in the
	// pre-push rewrite path (manual_commit_opf_rewrite.go).
	if len(opts.Prompts) > 0 {
		promptContent := RedactedJoinedPrompts(opts.Prompts)
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return filePaths, err
		}
		promptPath := checkpointSubtreePath(sessionDir, paths.PromptFileName)
		entries[promptPath] = object.TreeEntry{
			Name: promptPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
		filePaths.Prompt = "/" + promptPath
	}

	// The write boundary dedupes as a last line of defense, but duplicates
	// reaching it mean an upstream producer skipped mergeFilesTouched — warn
	// so that producer can be found rather than silently masked.
	filesTouched := NormalizeFilesTouched(opts.FilesTouched)
	if len(filesTouched) < len(opts.FilesTouched) {
		logging.Warn(logging.WithComponent(ctx, "checkpoint"),
			"files_touched reached the write boundary with duplicates",
			slog.String("session_id", opts.SessionID),
			slog.Int("reported", len(opts.FilesTouched)),
			slog.Int("unique", len(filesTouched)),
		)
	}

	// Write session-level metadata.json (Metadata with all fields including initial_attribution)
	sessionMetadata := Metadata{
		CheckpointID:                opts.CheckpointID,
		SessionID:                   opts.SessionID,
		Strategy:                    opts.Strategy,
		CreatedAt:                   checkpointCreatedAt(opts),
		Branch:                      opts.Branch,
		CommitSHA:                   opts.CommitSHA,
		CheckpointsCount:            opts.CheckpointsCount,
		SaveStepCount:               opts.SaveStepCount,
		FilesTouched:                filesTouched,
		Agent:                       opts.Agent,
		Model:                       opts.Model,
		TurnID:                      opts.TurnID,
		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
		CompactTranscriptStart:      compactTranscriptStart,
		TokenUsage:                  opts.TokenUsage,
		SkillEventsVersion:          skillEventsVersion(opts.SkillEvents),
		SkillEvents:                 opts.SkillEvents,
		SessionMetrics:              opts.SessionMetrics,
		Attribution:                 opts.Attribution,
		PromptAttributions:          opts.PromptAttributionsJSON,
		Summary:                     RedactSummary(opts.Summary),
		CLIVersion:                  versioninfo.Version,
		Kind:                        opts.Kind,
		ReviewSkills:                opts.ReviewSkills,
		ReviewPrompt:                opts.ReviewPrompt,
		InvestigateRunID:            opts.InvestigateRunID,
		InvestigateTopic:            opts.InvestigateTopic,
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
	if err != nil {
		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return filePaths, err
	}
	sessionMetadataPath := checkpointSubtreePath(sessionDir, paths.MetadataFileName)
	entries[sessionMetadataPath] = object.TreeEntry{
		Name: sessionMetadataPath,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	filePaths.Metadata = "/" + sessionMetadataPath

	return filePaths, nil
}

// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
// sessions is the complete sessions array (already built by the caller).
func (s *treeWriter) writeCheckpointSummary(opts WriteOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
	checkpointsCount, filesTouched, tokenUsage, err := s.reaggregateFromEntries(basePath, len(sessions), entries)
	if err != nil {
		return fmt.Errorf("failed to aggregate session stats: %w", err)
	}

	combinedAttribution := opts.CombinedAttribution
	hasReview := opts.HasReview
	hasInvestigation := opts.HasInvestigation
	// imported is the umbrella flag: true when any session in this checkpoint
	// was imported (Kind == "imported"). Compared as a literal because the
	// session package imports checkpoint, so we can't reference its constant.
	imported := opts.Kind == "imported"
	commitSHA := opts.CommitSHA
	rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
	if entry, exists := entries[rootMetadataPath]; exists {
		existingSummary, readErr := s.readSummaryFromBlob(entry.Hash)
		if readErr == nil {
			if combinedAttribution == nil {
				combinedAttribution = existingSummary.CombinedAttribution
			}
			if !hasReview {
				hasReview = existingSummary.HasReview
			}
			if !hasInvestigation {
				hasInvestigation = existingSummary.HasInvestigation
			}
			if !imported {
				imported = existingSummary.Imported
			}
			// A later write to the same checkpoint (e.g. a review session
			// attached to it) carries no CommitSHA; the imported anchor
			// must survive that rewrite rather than be cleared.
			if commitSHA == "" {
				commitSHA = existingSummary.CommitSHA
			}
		}
	}

	summary := CheckpointSummary{
		CheckpointID:        opts.CheckpointID,
		CLIVersion:          versioninfo.Version,
		Strategy:            opts.Strategy,
		Branch:              opts.Branch,
		CommitSHA:           commitSHA,
		CheckpointsCount:    checkpointsCount,
		FilesTouched:        filesTouched,
		Sessions:            sessions,
		TokenUsage:          tokenUsage,
		CombinedAttribution: combinedAttribution,
		HasReview:           hasReview,
		HasInvestigation:    hasInvestigation,
		Imported:            imported,
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return err
	}
	entries[rootMetadataPath] = object.TreeEntry{
		Name: rootMetadataPath,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	return nil
}

// backfillAttribution updates root-level checkpoint metadata fields that depend
// on the full set of sessions already written to the checkpoint.
func (s *GitStore) backfillAttribution(ctx context.Context, checkpointID id.CheckpointID, combinedAttribution *Attribution) error {
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}

	// Backfills require the branch to exist; a miss must not create it.
	if err := s.requireSessionsBranch(); err != nil {
		return err
	}

// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
// Use ReadSessionContent to read actual transcript/prompts/context.
// Returns nil, nil if the checkpoint doesn't exist.
//
// The storage format uses numbered subdirectories for each session (0-based):
//
//	<checkpoint-id>/
//	├── metadata.json      # CheckpointSummary with sessions map
//	├── 0/                 # First session
//	│   ├── metadata.json  # Session-specific metadata
//	│   ├── full.jsonl     # Raw agent transcript
//	│   └── transcript.jsonl  # Compact transcript (referenced by metadata.json)
//	├── 1/                 # Second session
//	└── ...
func (s *GitStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	checkpointTree, err := s.getCheckpointFetchingTree(ctx, checkpointID)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
	}

	return readSummaryFromCheckpointTree(checkpointTree)
}

// readSummaryFromCheckpointTree reads the root CheckpointSummary from a checkpoint
// tree (the tree holding metadata.json plus the numbered session dirs). It is
// shared by the git-branch store (which descends to <shard>/<id>) and the
// git-refs store (whose ref tree is the checkpoint tree directly). It returns
// (nil, nil) when metadata.json is absent so callers normalize a missing
// checkpoint to ErrCheckpointNotFound via the contract.
func readSummaryFromCheckpointTree(checkpointTree *FetchingTree) (*CheckpointSummary, error) {
	// Read root metadata.json as CheckpointSummary (auto-fetches blob if needed)
	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
	}

	content, err := metadataFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
	}

	var summary CheckpointSummary
	if err := json.Unmarshal([]byte(content), &summary); err != nil {
		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
	}

	return &summary, nil
}

// getSessionTree resolves the FetchingTree for a single session within a
// checkpoint. It returns ErrCheckpointNotFound when the checkpoint or session
// is missing; all session-level reads share this navigation.
func (s *GitStore) getSessionTree(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*FetchingTree, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	checkpointTree, err := s.getCheckpointFetchingTree(ctx, checkpointID)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	sessionTree, err := checkpointTree.Tree(strconv.Itoa(sessionIndex))
	if err != nil {
		return nil, fmt.Errorf("%w: session %d not found: %w", ErrCheckpointNotFound, sessionIndex, err)
	}
	return sessionTree, nil
}

// ReadSessionMetadata reads only the metadata.json for a specific session within a checkpoint.
// This is a lightweight read that avoids fetching transcript/prompt blobs.
// sessionIndex is 0-based.
func (s *GitStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error) {
	sessionTree, err := s.getSessionTree(ctx, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}
	return readSessionMetadataFromTree(sessionTree, sessionIndex)
}

// readSessionMetadataFromTree parses metadata.json from a session tree. Shared by
// both persistent backends, which differ only in how they navigate to the tree.
func readSessionMetadataFromTree(sessionTree *FetchingTree, sessionIndex int) (*Metadata, error) {
	metadataFile, err := sessionTree.File(paths.MetadataFileName)
	if err != nil {
		return nil, fmt.Errorf("metadata.json not found for session %d: %w", sessionIndex, err)
	}

	content, err := metadataFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("failed to read session metadata: %w", err)
	}

	var metadata Metadata
	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
		return nil, fmt.Errorf("failed to parse session metadata: %w", err)
	}

	return &metadata, nil
}

// ReadSessionMetadataAndPrompts reads session metadata and prompt text without
// requiring the raw transcript blob.
func (s *GitStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error) {
	sessionTree, err := s.getSessionTree(ctx, checkpointID, sessionIndex)
	if err != nil {
		return nil, "", err
	}
	return readSessionMetadataAndPromptsFromTree(sessionTree, sessionIndex)
}

func readSessionMetadataAndPromptsFromTree(sessionTree *FetchingTree, sessionIndex int) (*Metadata, string, error) {
	metadata, err := readSessionMetadataFromTree(sessionTree, sessionIndex)
	if err != nil {
		return nil, "", err
	}

	var prompts string
	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			prompts = content
		}
	}

	return metadata, prompts, nil
}

func (s *GitStore) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
	sessionTree, err := s.getSessionTree(ctx, checkpointID, sessionIndex)
	if err != nil {
		return "", err
	}
	return readSessionPromptsFromTree(sessionTree)
}

func readSessionPromptsFromTree(sessionTree *FetchingTree) (string, error) {
	file, err := sessionTree.File(paths.PromptFileName)
	if err != nil {
		return "", nil //nolint:nilerr // Missing prompt.txt means no recorded prompts.
	}
	content, err := file.Contents()
	if err != nil {
		return "", nil //nolint:nilerr // Keep committed prompt reads best-effort.
	}
	return content, nil
}

// ReadSessionContent reads the actual content for a specific session within a checkpoint.
// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
// Returns the session's metadata, transcript, prompts, and context.
// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist.
// Returns ErrNoTranscript if the session exists but has no transcript.
func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
	sessionTree, err := s.getSessionTree(ctx, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}
	return readSessionContentFromTree(ctx, sessionTree)
}

func readSessionContentFromTree(ctx context.Context, sessionTree *FetchingTree) (*SessionContent, error) {
	result := &SessionContent{}

	// Read session-specific metadata (auto-fetches blob if needed)
	var agentType types.AgentType
	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
				agentType = result.Metadata.Agent
			}
		}
	}

	// Read transcript (auto-fetches blobs if needed)
	if transcript, transcriptErr := readTranscriptFromTree(ctx, sessionTree, agentType); transcriptErr == nil && transcript != nil {
		result.Transcript = reinjectAssets(sessionTree, agentType, transcript)
		result.TranscriptBlobHashes = transcriptBlobHashesFromTreeEntries(sessionTree.RawEntries())
	}

	// Read prompts (auto-fetches blob if needed)
	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Prompts = content
		}
	}

	if len(result.Transcript) == 0 {
		return nil, ErrNoTranscript
	}

	return result, nil
}

// ReadLatestSessionContent is a convenience method that reads the latest session's content.
// runExplain routes to the appropriate explain function based on flags and the
// optional positional target.
func runExplain(ctx context.Context, w, errW io.Writer, sessionID, commitRef, checkpointID, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
	// Count mutually exclusive flags (--commit and --checkpoint are mutually exclusive)
	// --session is now a filter for the list view, not a separate mode
	flagCount := 0
	if commitRef != "" {
		flagCount++
	}
	if checkpointID != "" {
		flagCount++
	}
	// If --session is combined with --commit or --checkpoint, that's still an error
	if sessionID != "" && flagCount > 0 {
		return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
	}
	if flagCount > 1 {
		return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
	}

	// Route to appropriate handler
	if target != "" {
		return runExplainAuto(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
	}
	if commitRef != "" {
		return runExplainCommit(ctx, w, errW, commitRef, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
	}
	if checkpointID != "" {
		return runExplainCheckpoint(ctx, w, errW, checkpointID, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
	}

	// Default or with session filter: show list view (optionally filtered by session)
	return runExplainBranchWithFilter(ctx, w, errW, noPager, sessionID)
}

// explainTargetNotFoundError reports that the requested checkpoint target
// matched no committed or temporary checkpoint. It unwraps to
// checkpoint.ErrCheckpointNotFound so callers' errors.Is contracts keep
// working, while runExplainAuto can distinguish this resolution miss from a
// failure AFTER a successful match that happens to wrap the same sentinel
// (e.g. "failed to save summary: checkpoint not found" from a backfill
// against a backend missing the checkpoint) — those must surface verbatim,
// not be masked by the commit fallback's "no checkpoint or commit found".
type explainTargetNotFoundError struct{ target string }

func (e *explainTargetNotFoundError) Error() string {
	return fmt.Sprintf("%s: %s", checkpoint.ErrCheckpointNotFound, e.target)
}

func (e *explainTargetNotFoundError) Unwrap() error { return checkpoint.ErrCheckpointNotFound }

// shouldFallBackToCommitResolution reports whether the checkpoint path's error
// means "the target matched nothing", the only outcome that may fall through
// to git commit resolution.
func shouldFallBackToCommitResolution(err error) bool {
	var targetMiss *explainTargetNotFoundError
	return errors.As(err, &targetMiss)
}

// runExplainAuto resolves a positional target as either a checkpoint ID
// (or prefix) or a git commit ref. Ordering: checkpoint path first (which
// also handles shadow-branch temp checkpoints), falling back to commit
// resolution only on the target-miss error (explainTargetNotFoundError).
// --generate runs an ambiguity pre-check to avoid writing a summary to the
// wrong checkpoint on short-prefix collisions.
func runExplainAuto(ctx context.Context, w, errW io.Writer, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
	stop := startSpinner(errW, "Loading checkpoints")
	lookup, lookupErr := newExplainCheckpointLookup(ctx)
	stop(false)
	if lookup != nil {
		defer lookup.Close()
	}
	if generate {
		if err := runExplainAutoAmbiguityGuard(ctx, target, lookup, lookupErr); err != nil {
			return err
		}
	}
	checkpointErr := runExplainCheckpointWithLookup(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, lookupErr, summaryTimeoutSeconds)
	if checkpointErr == nil {
		return nil
	}
	// Fall back to commit resolution ONLY when nothing (committed or temp)
	// matched the target. Errors from steps AFTER a successful match — even
	// ones wrapping checkpoint.ErrCheckpointNotFound, like a summary backfill
	// failing against a backend missing the checkpoint — surface verbatim;
	// falling back would misreport them as "no checkpoint or commit found"
	// for a target that DID resolve. errCannotGenerateTemporaryCheckpoint
	// likewise signals we matched a temp checkpoint but --generate is
	// unsupported for it; a commit fallback there would produce a misleading
	// "no trailer" error for the shadow-branch commit.
	if !shouldFallBackToCommitResolution(checkpointErr) {
		return checkpointErr
	}
	logging.Debug(ctx, "explain auto: checkpoint lookup failed, trying commit fallback",
		slog.String("target", target),
		slog.String("checkpoint_error", checkpointErr.Error()))

	if lookupErr != nil {
		// Composed message beats errors.Join here — the latter renders
		// two lines (one per error) and users act on the first/stale one.
		return fmt.Errorf("no checkpoint matched %q, and commit fallback failed: %w", target, lookupErr)
	}
	hash, ambiguousMatches, resolveErr := resolveCommitUnambiguous(lookup.repo, target)
	if resolveErr != nil {
		if errors.Is(resolveErr, errAmbiguousCommitPrefix) {
			renderAmbiguousPrefixFailure(errW, target, "commits", buildAmbiguousCommitMatches(lookup.repo, ambiguousMatches))
			return NewSilentError(resolveErr)
		}
		logging.Debug(ctx, "explain auto: git ref resolution failed",
			slog.String("target", target),
			slog.String("error", resolveErr.Error()))
		return fmt.Errorf("no checkpoint or commit found matching %q", target)
	}
	commit, commitErr := lookup.repo.CommitObject(hash)
	if commitErr != nil {
		return fmt.Errorf("failed to get commit %s: %w", abbreviateCommitHash(lookup.repo, hash), commitErr)
	}
	cpID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
	if !hasCheckpoint {
		// Side-effect modes must error — silently succeeding would leave
		// scripts unable to distinguish "done" from "didn't happen".
		if generate || rawTranscript {
			return fmt.Errorf("cannot %s: commit %s has no Entire-Checkpoint trailer", generateOrRawLabel(generate), abbreviateCommitHash(lookup.repo, hash))
		}
		printNoTrailerMessage(w, lookup.repo, hash)
		return nil
	}
	logging.Debug(ctx, "explain auto: resolved commit to checkpoint via trailer",
		slog.String("target", target),
		slog.String("commit", abbreviateCommitHash(lookup.repo, hash)),
		slog.String("checkpoint_id", cpID.String()))
	if err := runExplainCheckpointWithLookup(ctx, w, errW, cpID.String(), noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, nil, summaryTimeoutSeconds); err != nil {
		// The user typed a commit, not this checkpoint ID — without the
		// trailer linkage the error reads as if they asked for an unknown ID.
		return fmt.Errorf("commit %s references checkpoint %s via its Entire-Checkpoint trailer: %w", abbreviateCommitHash(lookup.repo, hash), cpID, err)
	}
	return nil
}

// runExplainAutoAmbiguityGuard refuses --generate when the positional
// target resolves as both a git revision and a committed-checkpoint prefix.
// Writing a summary to the wrong checkpoint is destructive; read-only flows
// tolerate the same ambiguity by preferring the checkpoint path.
//
// Best-effort: on repo/list failures we return nil so the main flow
// surfaces the real error instead of double-reporting.
func runExplainAutoAmbiguityGuard(ctx context.Context, target string, lookup *explainCheckpointLookup, lookupErr error) error {
	// Targets longer than the longest possible checkpoint ID (a 26-char ULID)
	// can't be a prefix of one, so they can't be an ambiguous checkpoint target.
	if len(target) > id.MaxIDLength {
		return nil
	}
	if lookupErr != nil {
		logging.Warn(ctx, "explain ambiguity guard degraded: failed to prepare checkpoint lookup",
			"target", target,
			"error", lookupErr)
		return nil
	}
	hash, err := lookup.repo.ResolveRevision(plumbing.Revision(target))
	if err != nil {
		return nil //nolint:nilerr // target isn't a git ref
	}
	if lookup == nil {
		logging.Warn(ctx, "explain ambiguity guard degraded: checkpoint lookup unavailable",
			"target", target)
		return nil
	}
	if lookup.committed == nil {
		logging.Warn(ctx, "explain ambiguity guard degraded: committed checkpoint list unavailable",
			"target", target)
		return nil
	}
	for _, info := range lookup.committed {
		if strings.HasPrefix(info.CheckpointID.String(), target) {
			return fmt.Errorf("ambiguous target %q with --generate: matches both git revision %s and checkpoint prefix (e.g. %s)\nUse --commit <ref> or --checkpoint <id> to disambiguate", target, abbreviateCommitHash(lookup.repo, *hash), info.CheckpointID)
		}
	}
	return nil
}

// runExplainCheckpoint explains a specific checkpoint.
// Supports both committed checkpoints (by checkpoint ID) and temporary checkpoints (by git SHA).
// First tries to match committed checkpoints, then falls back to temporary checkpoints.
// When generate is true, generates an AI summary for the checkpoint.
// When force is true, regenerates even if a summary already exists.
// When rawTranscript is true, outputs only the raw transcript file (JSONL format).
// When searchAll is true, searches all commits without branch/depth limits (used for finding associated commits).
//

func runExplainCheckpoint(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
	return runExplainCheckpointWithLookup(ctx, w, errW, checkpointIDPrefix, noPager, verbose, full, rawTranscript, generate, force, searchAll, nil, nil, summaryTimeoutSeconds)
}

func runExplainCheckpointWithLookup(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, lookup *explainCheckpointLookup, lookupErr error, summaryTimeoutSeconds int) error {
	ownLookup := false
	if lookup == nil {
		var err error
		lookup, err = newExplainCheckpointLookup(ctx)
		if err != nil {
			return err
		}
		ownLookup = true
	} else if lookupErr != nil {
		return lookupErr
	}
	initialLookup := lookup
	defer func() {
		if ownLookup && initialLookup != nil {
			_ = initialLookup.Close()
		}
		if lookup != nil && lookup != initialLookup {
			_ = lookup.Close()
		}
	}()

	// Match the prefix locally; on miss, fetch from remote and retry once.
	matches, lookup := matchCheckpointPrefixWithRemoteFallback(ctx, errW, lookup, checkpointIDPrefix)

	var fullCheckpointID id.CheckpointID
	switch len(matches) {
	case 0:
		// Check temp checkpoints BEFORE returning errCannotGenerateTemporaryCheckpoint
		// so runExplainAuto can distinguish:
		//   - target matched a real temp checkpoint (sentinel returned, no fallback)
		//   - target matched nothing (explainTargetNotFoundError, safe to fall back to commit)
		// Previously the --generate path bailed before checking temp checkpoints,
		// which made runExplainAuto fall back to commit resolution for temp
		// checkpoint SHAs and produce a misleading "no trailer" error.
		//
		// --generate and --raw-transcript are mutually exclusive at the flag
		// layer, so rawTranscript is always false when generate is true; the
		// direct-to-w write path inside explainTemporaryCheckpoint is not
		// reachable here and won't leak partial output on error.
		tempStores, openErr := checkpoint.Open(ctx, lookup.repo, checkpoint.OpenOptions{ReadRemotes: strategy.CheckpointReadRemotes(ctx)})
		if openErr != nil {
			return fmt.Errorf("open checkpoint store: %w", openErr)
		}
		output, found, tempErr := explainTemporaryCheckpoint(ctx, w, errW, lookup.repo, tempStores.Ephemeral(), checkpointIDPrefix, verbose, full, rawTranscript)
		if tempErr != nil {
			return tempErr
		}
		if found {
			if generate {
				return fmt.Errorf("%w %s (only committed checkpoints supported)", errCannotGenerateTemporaryCheckpoint, checkpointIDPrefix)
			}
			outputExplainContent(w, output, noPager)
			return nil
		}
		return &explainTargetNotFoundError{target: checkpointIDPrefix}
	case 1:
		fullCheckpointID = matches[0]
	default:
		// Ambiguous prefix: render styled failure block, return SilentError so
		// main.go does not double-print. Matches the temporary-side and
		// commit-side ambiguity paths.
		ambig := buildAmbiguousCheckpointMatches(matches, lookup.committed)
		renderAmbiguousPrefixFailure(errW, checkpointIDPrefix, "committed checkpoints", ambig)
		return NewSilentError(fmt.Errorf("%w: %s matches %d checkpoints", errAmbiguousCommitPrefix, checkpointIDPrefix, len(matches)))
	}

	// Fast-fail on imported checkpoints before the expensive content load.
	// --generate is read-only-rejected for imported history, so fetching
	// transcript blobs first (prefetch + ReadLatestSessionContent inside
	// loadCheckpointForExplain) is wasted work for a guaranteed rejection.
	// Imported lives in the checkpoint metadata, so a metadata-only
	// ReadCheckpoint settles it without reading any session content. On the
	// non-imported path loadCheckpointForExplain re-reads this summary, but
	// that extra metadata-only read is cheap and happens only under
	// --generate — the skipped blob prefetch + transcript load on the
	// imported path is the larger win.
	if generate {
		summary, summaryErr := checkpoint.ReadCheckpoint(ctx, lookup.store, fullCheckpointID)
		if summaryErr != nil {
			return fmt.Errorf("failed to read checkpoint %s: %w", fullCheckpointID, summaryErr)
		}
		if summary.Imported {
			return fmt.Errorf("cannot generate a summary for imported checkpoint %s: imported history is read-only", fullCheckpointID)
		}
	}

	// One spinner covers the entire data-loading pipeline: prefetch's
	// missing-blob analysis (one batched cat-file over the subtree, which
	// can still take a moment on a deep one), the prefetch fetch
	// itself, the committed checkpoint metadata read, session content
	// reads, and getAssociatedCommits' git log walk. Stop strictly before
	// any write to w (stdout) so stderr spinner frames and stdout output
	// never interleave.
	stopLoad := startSpinner(errW, fmt.Sprintf("Loading checkpoint %s", fullCheckpointID))

	summary, content, err := loadCheckpointForExplain(ctx, lookup, fullCheckpointID)
	if err != nil {
		stopLoad(false)
		return err
	}
	// Handle summary generation — uses raw transcript. Imported history was
	// already rejected above, before the content load.
	if generate {
		if err := ensureCheckpointPolicyAllowsCheckpointData(ctx, lookup.repo); err != nil {
			stopLoad(false)
			return err
		}
		stopLoad(false) // generation prints its own progress to w/errW
		// RefFetcher: the summary backfill's absence probe fetches a ref that
		// exists remotely but not locally (written/migrated on another
		// machine), bounded by the write-probe budget.
		writeStores, openErr := checkpoint.Open(ctx, lookup.repo, checkpoint.OpenOptions{
			RefFetcher:  remote.BoundedCheckpointRefFetcher(remote.WriteProbeFetchBudget),
			ReadRemotes: strategy.CheckpointReadRemotes(ctx),
		})
		if openErr != nil {
			return fmt.Errorf("open checkpoint store: %w", openErr)
		}
		if err := generateCheckpointSummary(ctx, w, errW, writeStores.Persistent, fullCheckpointID, summary, content, force, summaryTimeoutSeconds); err != nil {
			return err
		}
		// Reload to get the updated summary.
		stopLoad = startSpinner(errW, fmt.Sprintf("Reloading checkpoint %s", fullCheckpointID))
		reopened, openErr := checkpoint.Open(ctx, lookup.repo, checkpoint.OpenOptions{
			BlobFetcher:           FetchBlobsByHash,
			RefFetcher:            FetchCheckpointRef,
			MetadataBranchFetcher: FetchMetadataFromCheckpointRemote,
	committed, err := store.List(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
	}
	lookup.committed = committed
	closeOnError = false
	return lookup, nil
}

// generateCheckpointSummary generates an AI summary for a checkpoint and persists it.
// The summary is generated from the scoped transcript (only this checkpoint's portion),
// not the entire session transcript.
//
// summaryTimeoutSeconds is the per-invocation --summary-timeout-seconds flag
// value (0 = unset). Effective precedence for the deadline: flag > settings >
// no deadline. See resolveSummaryTimeout for the resolution.
func generateCheckpointSummary(ctx context.Context, w, errW io.Writer, store checkpoint.Writer, checkpointID id.CheckpointID, cpSummary *checkpoint.CheckpointSummary, content *checkpoint.SessionContent, force bool, summaryTimeoutSeconds int) error {
	// Check if summary already exists
	if content.Metadata.Summary != nil && !force {
		return renderExplainFailure(errW, "Summary already exists", []explainRow{
			{Label: "id", Value: checkpointID.String()},
			{Label: "try", Value: fmt.Sprintf("entire checkpoint explain --generate --force %s", checkpointID)},
		}, fmt.Errorf("checkpoint %s already has a summary", checkpointID))
	}

	// Check if transcript exists
	if len(content.Transcript) == 0 {
		return renderExplainFailure(errW, "Checkpoint has no transcript", []explainRow{
			{Label: "id", Value: checkpointID.String()},
		}, fmt.Errorf("checkpoint %s has no transcript to summarize", checkpointID))
	}

	// Scope the transcript to only this checkpoint's portion
	scopedTranscript := scopeTranscriptForCheckpoint(content.Transcript, content.Metadata.GetTranscriptStart(), content.Metadata.Agent)
	if len(scopedTranscript) == 0 {
		return renderExplainFailure(errW, "Checkpoint has no transcript content (scoped)", []explainRow{
			{Label: "id", Value: checkpointID.String()},
		}, fmt.Errorf("checkpoint %s has no transcript content for this checkpoint (scoped)", checkpointID))
	}
	provider, err := resolveCheckpointSummaryProvider(ctx, w)
	if err != nil {
		return fmt.Errorf("failed to resolve summary provider: %w", err)
	}
	scopedTranscript = maybeCompactExternalTranscript(ctx, scopedTranscript, content.Metadata.Agent)

	// Generate summary using shared helper
	logging.Info(ctx, "generating checkpoint summary")
	if errW != nil {
		fmt.Fprintf(errW, "Generating checkpoint summary... (transcript: %s, provider: %s)\n",
			humanizeBytes(len(scopedTranscript)), provider.Name)
	}

	timeout := resolveSummaryTimeout(ctx, summaryTimeoutSeconds)

	attempt := newSummaryAttempt(provider.Name, timeout)
	// Set streaming eagerly from the provider's capability rather than waiting
	// for the first progress event: a streaming provider that stalls before
	// emitting anything should still get the streaming timeout diagnostic
	// ("never sent its request"), not "provider produced no output".
	attempt.streaming = provider.Streaming
	progressWriter := newSummaryProgressWriter(errW, attempt)

	start := time.Now()
	summary, err := generateCheckpointAISummary(
		ctx, scopedTranscript, cpSummary.FilesTouched,
		content.Metadata.Agent, provider.Generator,
		timeout, progressWriter.handle, attempt,
	)
	if err != nil {
		progressWriter.Flush()
		label, rows, structured := formatCheckpointSummaryError(err, attempt)
		styles := newStatusStyles(errW)
		fmt.Fprint(errW, styles.renderFailure(label, rows))
		return NewSilentError(structured)
	}
	elapsed := time.Since(start)

	if err := store.Write(ctx, checkpoint.SessionSummary{CheckpointID: checkpointID, Summary: summary}); err != nil {
		return fmt.Errorf("failed to save summary: %w", err)
	}

	styles := newStatusStyles(w)
	rows := summaryProviderRows(provider)
	rows = append(rows, explainRow{Label: "duration", Value: formatSummaryDuration(elapsed)})
	fmt.Fprint(w, styles.renderSuccess(fmt.Sprintf("Summary generated for %s", checkpointID), rows))
	return nil
}

// formatSummaryDuration rounds wall-clock generation time to a human-friendly value.
func formatSummaryDuration(d time.Duration) string {
	return d.Round(100 * time.Millisecond).String()
}

func maybeCompactExternalTranscript(ctx context.Context, scopedTranscript []byte, agentType types.AgentType) []byte {
	if transcriptHasSummaryContent(scopedTranscript, agentType) {
		return scopedTranscript
	}

