package cli

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/telemetry"
	"github.com/entireio/cli/cmd/entire/cli/versioncheck"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/spf13/cobra"
)

// External-command resolution, kubectl-style. When the user invokes
// `entire <name>` and <name> isn't a built-in subcommand, look for an
// `entire-<name>` binary on PATH and exec it with the remaining args.
// Stdio and exit codes pass through. Binaries matching the agent
// protocol prefix are reserved for the external agent registry and
// skipped here.
const (
	pluginBinaryPrefix      = "entire-"
	agentPluginBinaryPrefix = "entire-agent-"
)

// selfUpdatePluginName is the plugin that replaces the entire binary on
// disk (`entire upgrade` → entire-upgrade).
const selfUpdatePluginName = "upgrade"

// postPluginVersionCheck is a test seam for the version-check notice that
// fires after a successful plugin run.
var postPluginVersionCheck = versioncheck.CheckAndNotify

// MaybeRunPlugin returns (true, exitCode) when an external command was
// resolved and run. On launch failure (e.g. missing executable bit)
// returns (true, 1) after printing to stderr. On no-match returns
// (false, 0) so the caller can fall through to Cobra.
//
// Telemetry and the version-check notice mirror Cobra's PersistentPostRun
// behavior for built-ins: both fire only on a successful (exit-0) run.
func MaybeRunPlugin(ctx context.Context, rootCmd *cobra.Command, args []string) (handled bool, exitCode int) {
	binPath, pluginArgs, ok := resolvePlugin(rootCmd, args)
	if !ok {
		return false, 0
	}
	pluginName := args[0]
	exitCode = runPlugin(ctx, pluginName, binPath, pluginArgs)
	if exitCode == 0 {
		maybeTrackPluginInvocation(ctx, pluginName)
		// Stderr, matching the built-in PersistentPostRun: the plugin's own
		// stdout may be machine-readable and piped.
		//
		// Skipped after a self-update: this process still carries the
		// pre-upgrade compiled-in version, so the check would see itself as
		// outdated and prompt to redo the upgrade that just completed.
		if pluginName != selfUpdatePluginName {
			postPluginVersionCheck(ctx, os.Stderr, versioninfo.Version)
		}
	}
	return true, exitCode
}

// maybeTrackPluginInvocation fires telemetry only for plugins on the
// official allowlist. Third-party plugin names are never sent — see
// IsOfficialPlugin for the rationale.
func maybeTrackPluginInvocation(ctx context.Context, pluginName string) {
	if !IsOfficialPlugin(pluginName) {
		return
	}
	s, err := LoadEntireSettings(ctx)
	if err != nil {
		return
	}
	if !s.IsTelemetryEnabled() {
		return
	}
	telemetry.TrackPluginDetached(pluginName, s.Enabled, versioninfo.Version)
}

func resolvePlugin(rootCmd *cobra.Command, args []string) (binPath string, pluginArgs []string, ok bool) {
	if len(args) == 0 {
		return "", nil, false
	}
	name := args[0]
	if !isPluginCandidate(name) {
		return "", nil, false
	}
	// Cobra adds `help` and `completion` to the command tree inside Execute,
	// not in the constructor / SetHelpCommand. Without priming them, Find
	// reports "unknown command" for those names and an entire-help (or
	// entire-completion) binary on PATH would shadow the built-in. Both
	// initializers are idempotent and Execute calls them again later.
	rootCmd.InitDefaultHelpCmd()
	rootCmd.InitDefaultCompletionCmd(args...)
	// Built-in commands always win.
	if cmd, _, err := rootCmd.Find(args); err == nil && cmd != rootCmd {
		return "", nil, false
	}
	binName := pluginBinaryPrefix + name
	binPath, err := exec.LookPath(binName)
	if err != nil {
		// LookPath conflates "not on PATH" with "found but not executable".
		// Distinguish: if a file with this name exists on PATH but isn't
		// executable, surface that as a launch error rather than falling
		// through to Cobra's generic unknown-command path.
		if p, found := findInaccessiblePlugin(binName); found {
			return p, args[1:], true
		}
		return "", nil, false
	}
	if isAgentProtocolBinary(binPath) {
		return "", nil, false
	}
	return binPath, args[1:], true
}

// findInaccessiblePlugin scans PATH for a non-directory file with the
// given name. Only meaningful after exec.LookPath has already failed —
// indicates the file exists but lacks the executable bit (or the
// equivalent platform-specific accessibility).
//
// The scan goes through execx.PathScanDirs, not a bare split: the rule that
// only absolute entries are scanned is shared with the external-agent
// scanner, and two copies of it is how they drifted apart in the first place.
// The rule matters especially here, because this function runs only after
// LookPath has failed. LookPath's error does not distinguish exec.ErrDot (its
// refusal to resolve a match found through a relative PATH entry) from a
// genuine "exists but not executable", so a scan that re-walked relative
// entries would blindly re-find the exact binary LookPath just correctly
// refused. runPlugin then execs it via a path containing a separator, which
// bypasses exec.Command's own ErrDot re-check, since that only fires for a
// bare name with no separator.
func findInaccessiblePlugin(filename string) (string, bool) {
	for _, dir := range execx.PathScanDirs() {
		candidate := filepath.Join(dir, filename)
		info, err := os.Stat(candidate)
		if err != nil || info.IsDir() {
			continue
		}
		return candidate, true
	}
	return "", false
}

// isPluginCandidate reports whether name is a syntactically valid plugin
// name the dispatcher should attempt to resolve. It is a thin bool wrapper
// over validatePluginName so the dispatcher's gate and the managed store's
// install-time check can never drift.
func isPluginCandidate(name string) bool {
	return validatePluginName(name) == nil
}

// isAgentProtocolBinary returns true when the binary name is reserved for
// the external agent protocol. Strip Windows extensions first so
// `entire-agent-foo.exe` is also recognized.
func isAgentProtocolBinary(binPath string) bool {
	base := external.StripExeExt(filepath.Base(binPath))
	return strings.HasPrefix(base, agentPluginBinaryPrefix)
}

// runPlugin executes the resolved plugin binary, propagating its exit code.
// On context cancellation the child gets SIGINT (with a 5s grace before the
// runtime falls back to SIGKILL) so plugins can clean up. Terminal signals
// reach the child directly via the shared process group.
func runPlugin(ctx context.Context, pluginName, binPath string, args []string) int {
	cmd := exec.CommandContext(ctx, binPath, args...)
	cmd.Cancel = func() error { return cmd.Process.Signal(os.Interrupt) }
	cmd.WaitDelay = 5 * time.Second
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	extras := []string{"ENTIRE_CLI_VERSION=" + versioninfo.Version}
	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
		extras = append(extras, "ENTIRE_REPO_ROOT="+repoRoot)
	}
	// Per-plugin durable storage. Passed regardless of where the binary lives
	// so plugins installed via raw PATH and via `entire plugin install` get
	// the same contract. The dir is not pre-created — that's the plugin's
	// responsibility on first use.
	//
	// PluginDataDir can only fail in degenerate environments (no resolvable
	// home dir, or a relative ENTIRE_PLUGIN_DIR override). The plugin name
	// itself already passed isPluginCandidate in resolvePlugin, so the name
	// validator branch can't fire here. Proceed without the var rather than
	// refuse to launch: a misconfigured environment is the user's problem to
	// surface, not a reason to break plugins that don't read the var. The
	// failure is logged at debug rather than printed to stderr — printing
	// would noise every plugin invocation in a degenerate env.
	parentEnv := os.Environ()
	if dataDir, err := PluginDataDir(pluginName); err == nil {
		extras = append(extras, pluginEnvPluginData+"="+dataDir)
	} else {
		// Strip any inherited value so the plugin doesn't silently see a
		// value we never sanctioned. Without this strip, a user with
		// ENTIRE_PLUGIN_DATA_DIR pre-set in their shell would have that
		// value pass through (ENTIRE_* is in the pluginEnv allowlist
		// prefix), even though resolution here failed.
		parentEnv = removeEnvKey(parentEnv, pluginEnvPluginData)
		logging.Debug(ctx, "ENTIRE_PLUGIN_DATA_DIR unset for plugin",
			slog.String("plugin", pluginName),
			slog.String("error", err.Error()))
	}
	cmd.Env = pluginEnv(parentEnv, extras...)

	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return exitErr.ExitCode()
		}
		// Prefix with the plugin name so users can tell parent vs child
		// errors apart in mixed stderr.
		fmt.Fprintf(os.Stderr, "Failed to run plugin %s: %v\n", filepath.Base(binPath), err)
		return 1
	}
	return 0
}
package cli

import (
	"runtime"
	"strings"
)

// Plugin process environment is filtered, not inherited wholesale, so that
// credentials and other tool-specific config don't leak into third-party
// binaries on PATH. The threat model is "defense in depth" — a malicious
// plugin can still read files under $HOME — but a small allowlist makes
// accidental exposure (AWS_*, GITHUB_TOKEN, OPENAI_API_KEY) require an
// explicit user opt-in.

// pluginEnvAllowed is the exact-match allowlist of OS-plumbing and
// TUI-detection variables that virtually every program needs. Add entries
// here only when the whole namespace is unambiguously non-credential.
var pluginEnvAllowed = map[string]struct{}{
	// POSIX basics
	"PATH": {}, "HOME": {}, "USER": {}, "LOGNAME": {},
	"SHELL": {}, "PWD": {}, "TMPDIR": {}, "TZ": {},

	// Locale (LC_* covered by prefix below)
	"LANG": {}, "LANGUAGE": {},

	// Terminal / color rendering
	"TERM": {}, "TERM_PROGRAM": {}, "TERM_PROGRAM_VERSION": {},
	"COLORTERM": {}, "NO_COLOR": {}, "FORCE_COLOR": {},
	"CLICOLOR": {}, "CLICOLOR_FORCE": {},

	// CI detection — broad set because most tools can't detect CI any
	// other way and many writeups assume these are visible.
	"CI": {}, "GITHUB_ACTIONS": {}, "GITLAB_CI": {},
	"BUILDKITE": {}, "CIRCLECI": {}, "JENKINS_URL": {},
	"TEAMCITY_VERSION": {}, "TRAVIS": {},

	// Proxies. curl and git read both upper- and lowercase forms; we keep
	// both because the user's shell may set either.
	"HTTP_PROXY": {}, "HTTPS_PROXY": {}, "NO_PROXY": {}, "ALL_PROXY": {},
	"http_proxy": {}, "https_proxy": {}, "no_proxy": {}, "all_proxy": {},

	// SSH agent — plugins that fetch via git/ssh keep working.
	"SSH_AUTH_SOCK": {}, "SSH_CONNECTION": {},

	// Windows essentials. Names are upper-case here; lookup is
	// case-insensitive on Windows.
	"SYSTEMROOT": {}, "WINDIR": {}, "COMSPEC": {}, "PATHEXT": {},
	"APPDATA": {}, "LOCALAPPDATA": {}, "PROGRAMDATA": {},
	"PROGRAMFILES": {}, "PROGRAMFILES(X86)": {},
	"USERPROFILE": {}, "USERNAME": {}, "HOMEDRIVE": {}, "HOMEPATH": {},

	// Documented in CLAUDE.md as the toggle for accessibility mode.
	"ACCESSIBLE": {},
}

// pluginEnvPrefixes are namespaces we either own (ENTIRE_*) or that are
// long-standing passthrough conventions (LC_*, XDG_*).
var pluginEnvPrefixes = []string{
	"ENTIRE_",
	"LC_",
	"XDG_",
}

// pluginEnvOverrideVar lets a user opt names back into the plugin env
// without a CLI release. Comma-separated list of exact names or
// `PREFIX_*` wildcards. Example:
//
//	ENTIRE_PLUGIN_ENV="AWS_*,GH_TOKEN,EDITOR"
const pluginEnvOverrideVar = "ENTIRE_PLUGIN_ENV"

// pluginEnv builds the child environment from the parent. Only allowlisted
// names plus user-declared overrides are forwarded. Caller-provided extras
// are appended verbatim; per cmd/exec docs, when Env contains duplicate
// keys the last one wins, so extras override any matching parent value.
func pluginEnv(parent []string, extra ...string) []string {
	exact, prefixes := parsePluginEnvOverride(lookupEnv(parent, pluginEnvOverrideVar))
	out := make([]string, 0, len(parent)+len(extra))
	for _, kv := range parent {
		eq := strings.IndexByte(kv, '=')
		if eq <= 0 {
			continue
		}
		if isPluginEnvAllowed(kv[:eq], exact, prefixes) {
			out = append(out, kv)
		}
	}
	out = append(out, extra...)
	return out
}

func isPluginEnvAllowed(name string, userExact map[string]struct{}, userPrefixes []string) bool {
	if _, ok := pluginEnvAllowed[name]; ok {
		return true
	}
	if runtime.GOOS == windowsGOOS {
		// Env var names are case-insensitive on Windows. The allowlist
		// stores the canonical upper-case form, so normalize here.
		if _, ok := pluginEnvAllowed[strings.ToUpper(name)]; ok {
			return true
		}
	}
	for _, p := range pluginEnvPrefixes {
		if hasPrefixOSAware(name, p) {
			return true
		}
	}
	if _, ok := userExact[name]; ok {
		return true
	}
	for _, p := range userPrefixes {
		if hasPrefixOSAware(name, p) {
			return true
		}
	}
	return false
}

// parsePluginEnvOverride splits the comma-separated override into exact
// names and prefix patterns (`FOO_*`). Whitespace around items is trimmed.
func parsePluginEnvOverride(s string) (exact map[string]struct{}, prefixes []string) {
	if s == "" {
		return nil, nil
	}
	exact = map[string]struct{}{}
	for _, raw := range strings.Split(s, ",") {
		item := strings.TrimSpace(raw)
		if item == "" {
			continue
		}
		if strings.HasSuffix(item, "*") {
			prefixes = append(prefixes, strings.TrimSuffix(item, "*"))
			continue
		}
		exact[item] = struct{}{}
	}
	return exact, prefixes
}

// lookupEnv returns the value of name from a KEY=VALUE slice, or empty if
// absent. Used to read ENTIRE_PLUGIN_ENV out of the parent slice without
// touching process state, so tests stay parallel-safe.
func lookupEnv(env []string, name string) string {
	prefix := name + "="
	for _, kv := range env {
		if strings.HasPrefix(kv, prefix) {
			return kv[len(prefix):]
		}
	}
	return ""
}

func hasPrefixOSAware(name, prefix string) bool {
	if runtime.GOOS == windowsGOOS {
		return strings.HasPrefix(strings.ToUpper(name), strings.ToUpper(prefix))
	}
	return strings.HasPrefix(name, prefix)
}
package cli

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"golang.org/x/mod/semver"
	"gopkg.in/yaml.v3"
)

// Managed-install manifests. A plugin installed from a remote repository
// gets a per-plugin home under the managed dir:
//
//	<plugin-root>/pkg/<name>/entire-<name>[.exe]   the binary
//	<plugin-root>/pkg/<name>/manifest.yml          install provenance
//
// The bin/ dir remains the only dispatch surface — pkg/ binaries are
// linked into bin/ via the same symlink→hardlink→copy fallback as local
// installs, so the kubectl-style resolver in plugin.go never changes.
//
// Local-dev installs (`entire plugin install ./path`) bypass pkg/ entirely
// and have no manifest; ListPluginManifests simply doesn't see them.
const (
	pluginManagedPkgSubdir = "pkg"
	pluginManifestFileName = "manifest.yml"
	// windowsExeExt is the extension Windows executables need.
	windowsExeExt = ".exe"
	// maxPluginManifestSize bounds manifest.yml. We write it ourselves, but a
	// read with no ceiling is a ceiling of "however large the file on disk is",
	// and this one sits in a directory the user can edit.
	maxPluginManifestSize = 1 << 20
)

// readFileLimited reads at most limit bytes from path, erroring rather than
// silently truncating when the file is larger. os.ReadFile has no ceiling: it
// sizes its buffer from the file and reads to EOF, so every caller inherits
// whatever is on disk.
// pluginPkgName renders a plugin's pkg directory as a name inside pluginRoot.
// The name is validated first, as PluginPkgDir does, but the root is what makes
// that validation a defence rather than the only one.
func pluginPkgName(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	return pluginManagedPkgSubdir + "/" + name, nil
}

// readFileLimitedIn is readFileLimited for a name inside root.
func readFileLimitedIn(root *os.Root, name string, limit int64) ([]byte, error) {
	f, err := osroot.OpenNoFollow(root, name)
	if err != nil {
		// Returned bare so callers can still test it with errors.Is against
		// os.ErrNotExist — LoadPluginManifest depends on that to report an
		// absent manifest as (nil, nil) rather than a failure.
		return nil, err //nolint:wrapcheck // see above
	}
	defer f.Close()
	return readWithinLimit(f, limit)
}

func readFileLimited(path string, limit int64) ([]byte, error) {
	f, err := os.Open(path) //nolint:gosec // paths here are inside the managed plugin tree or our cache
	if err != nil {
		// Returned bare so callers can still test it with errors.Is against
		// os.ErrNotExist — LoadPluginManifest depends on that to report an
		// absent manifest as (nil, nil) rather than a failure.
		return nil, err //nolint:wrapcheck // see above
	}
	defer f.Close()
	data, err := readWithinLimit(f, limit)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", filepath.Base(path), err)
	}
	return data, nil
}

// pluginBinaryName returns the on-disk executable name for a bare plugin
// name: entire-<name>, plus the Windows extension where the host needs it.
func pluginBinaryName(name string) string {
	if runtime.GOOS == windowsGOOS {
		return pluginBinaryPrefix + name + windowsExeExt
	}
	return pluginBinaryPrefix + name
}

// PluginManifest records how a managed plugin was installed. Settings
// configure behavior; manifests record facts. The dependency list is
// copied from the plugin's metadata at install time so reverse-dependency
// checks (remove guard, doctor) work offline.
type PluginManifest struct {
	// Name is the bare plugin name ("run" for entire-run).
	Name string `yaml:"name"`
	// RepoURL is the full git URL the plugin was installed from.
	RepoURL string `yaml:"repo_url"`
	// Tag is the git tag that was installed (e.g. "v0.2.1").
	Tag string `yaml:"tag"`
	// Asset is the release asset filename the binary came from. Empty for
	// raw-binary downloads where the asset name equals the binary name.
	Asset string `yaml:"asset,omitempty"`
	// SHA256 is the hex digest of the downloaded asset.
	SHA256 string `yaml:"sha256,omitempty"`
	// BinarySHA256 is the hex digest of the installed binary under
	// pkg/<name>/. Distinct from SHA256, which covers the downloaded asset —
	// usually an archive, and discarded with the staging dir. Recording the
	// binary is what lets `plugin doctor` detect post-install tampering.
	BinarySHA256 string `yaml:"binary_sha256,omitempty"`
	// Unverified records that no checksum manifest authenticated the
	// download (installed with --allow-unverified). Surfaced by doctor.
	Unverified bool `yaml:"unverified,omitempty"`
	// Pinned marks installs done with --pin; upgrade skips them.
	Pinned bool `yaml:"pinned,omitempty"`
	// InstalledAt is when the install (or last upgrade) completed.
	InstalledAt time.Time `yaml:"installed_at,omitempty"`
	// Requires is the dependency list from the plugin's entire-plugin.yml
	// at the installed tag.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// PluginRequirement declares a dependency on another plugin. Shared between
// the author-side metadata file (entire-plugin.yml) and the install-side
// manifest so the two can never drift.
//
// There is deliberately no repo_url. A missing dependency resolves by name
// through the plugin index, so the URL a dependency install fetches from always
// comes from the curated catalog rather than from the requiring plugin's author.
// With an author-supplied URL, installing one plugin meant fetching and
// executing a binary from a URL its author chose — and dependency planning
// contacted that URL *before* the confirmation prompt. The capability is not
// gone, the authority moved: a user can still install an out-of-catalog
// dependency by URL themselves, with the usual untrusted-source prompt, after
// which the requirement is satisfied. Consent belongs to the user, not the
// author.
//
// A dependency must therefore be indexed before a dependent can ship, the same
// constraint krew, Homebrew and apt impose.
type PluginRequirement struct {
	// Name is the bare plugin name of the dependency, resolved through the
	// plugin index.
	Name string `yaml:"name"`
	// MinVersion is the minimum acceptable tag (e.g. "v0.2.0"). Minimum
	// only — there is deliberately no range syntax.
	MinVersion string `yaml:"min_version,omitempty"`
}

// PluginMetadata is the author-side declaration committed at the root of a
// plugin repository as entire-plugin.yml. Everything is optional — a repo
// without the file installs fine; the name then derives from the repo URL.
type PluginMetadata struct {
	// Name is the bare plugin name. When empty, derived from the repo URL
	// basename (entire-run → run).
	Name string `yaml:"name,omitempty"`
	// Description is a one-line summary shown by info/search.
	Description string `yaml:"description,omitempty"`
	// DownloadURL overrides the per-forge release-asset URL convention.
	// Template placeholders: {name} {tag} {version} {os} {arch} {asset}.
	// When {asset} is present, candidate asset filenames are substituted;
	// otherwise the expanded template is fetched as-is.
	DownloadURL string `yaml:"download_url,omitempty"`
	// Requires lists plugins this plugin needs at runtime.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// pluginMetadataFileName is the well-known path of the author-side metadata
// file at the root of a plugin repository.
const pluginMetadataFileName = "entire-plugin.yml"

// ParsePluginMetadata decodes entire-plugin.yml content.
//
// Decoding is lenient: unknown keys are ignored, matching the choice made for
// index.json. Both are artifacts read by every CLI version ever shipped, and
// refusing one an older binary doesn't fully understand breaks it permanently
// for everyone on that version — the plugin author cannot fix it for them.
// entire-plugin.yml has no version field to gate on either, so the first author
// to adopt any future field (min_cli_version, bin_name, …) would break installs
// on every older CLI.
//
// This deliberately gives up catching author typos here, which strict decoding
// did. The trade is asymmetric: a misspelled key costs the author one confused
// test run against their own plugin, while a forward-compatibility break is
// unfixable and fleet-wide. Author-side validation belongs in a lint command,
// not in the hot path every user's install runs through.
func ParsePluginMetadata(data []byte) (*PluginMetadata, error) {
	var meta PluginMetadata
	dec := yaml.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&meta); err != nil {
		// An empty or comment-only stream decodes to io.EOF. The file is
		// documented as optional and a *missing* one is fine, so a committed
		// placeholder must not be fatal at every tag. An explicit "---" already
		// behaved this way; align the empty cases with it.
		if !errors.Is(err, io.EOF) {
			return nil, fmt.Errorf("parsing %s: %w", pluginMetadataFileName, err)
		}
		meta = PluginMetadata{}
	}
	if meta.Name != "" {
		if err := validatePluginName(meta.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid name: %w", pluginMetadataFileName, err)
		}
	}
	for _, req := range meta.Requires {
		if err := validatePluginName(req.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid requirement: %w", pluginMetadataFileName, err)
		}
