	if !imageextract.HasPlaceholders(transcript) {
		return transcript
	}
	codec := imageextract.CodecFor(agentType)
	if codec == nil {
		return transcript
	}
	// No blob-integrity check is needed here: git content-addresses every asset
	// blob, so a corrupt/truncated fetch fails object verification and Contents()
	// errors out (leaving the placeholder). The manifest's sha256 is external
	// metadata, not a second integrity gate — and since writeAssets derives both
	// the blob and the sha256 from the same bytes, they can never disagree.
	out, err := codec.ReinjectImages(transcript, func(name string) (agent.CompactedTranscriptAsset, bool) {
		f, ferr := sessionTree.File(paths.AssetsDir + name)
		if ferr != nil {
			return agent.CompactedTranscriptAsset{}, false
		}
		content, cerr := f.Contents()
		if cerr != nil {
			return agent.CompactedTranscriptAsset{}, false
		}
		return agent.CompactedTranscriptAsset{Name: name, Data: []byte(content)}, true
	})
	if err != nil {
		return transcript
	}
	return out
}"},{"rank":3,"score":35.1156,"file_path":"cmd/entire/cli/checkpoint/routing_store.go","start_line":157,"end_line":164,"focus_line":157,"snippet_start_line":157,"snippet_end_line":164,"symbol_start_line":157,"symbol_end_line":164,"language":"Go","kind":"method","symbol_id":"local/cli:Go:cmd/entire/cli/checkpoint/routing_store.go:method:kindRoutingStore.ReadSessionMetadata","symbol_name":"ReadSessionMetadata","qualified_name":"kindRoutingStore.ReadSessionMetadata","signature":"func (s *kindRoutingStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error)","signals":["path","body","signature","symbol-name","complete-symbol"],"snippet":"func (s *kindRoutingStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error) {
