		} else {
			sb.WriteString(md)
		}
	} else {
		intent := extractIntent(scopedPrompts, content.Prompts)

		var files []string
		if verbose || full {
			files = meta.FilesTouched
		}

		hint := fmt.Sprintf("Not generated yet. Run `entire checkpoint explain --generate %s` to create an AI summary.", checkpointID)
		switch src, crossRepo := crossRepoReadSource(ctx); {
		case summary != nil && summary.Imported:
			// Imported history is read-only; --generate is refused for it, so
			// don't point users at a command that will error out.
			hint = "No summary. Imported history is read-only, so summaries cannot be generated."
		case crossRepo:
			// Same reasoning across repos: --generate is rejected with --repo,
			// and a summary is stored by the repo that owns the checkpoint, so
			// the default hint names a command that cannot succeed here.
			hint = fmt.Sprintf("No summary stored for this checkpoint. Summaries are generated in the repo that owns it (%s).", src)
		}
		md := buildNoSummaryMarkdown(intent, files, hint)
		sb.WriteString(renderExplainBody(w, md))
	}

	if verbose || full {
		label := "Transcript (checkpoint scope)"
		if full {
			label = "Transcript (full session)"
		}
		sb.WriteString("\n")
		sb.WriteString(styles.sectionRule(label, styles.width))
		sb.WriteString("\n")
		// Compact after scoping: CheckpointTranscriptStart indexes the stored
		// format, and compaction changes line counts.
		displayFull := content.Transcript
		displayScoped := scopedTranscript
		if full && len(displayFull) > 0 {
			displayFull = maybeCompactExternalTranscript(ctx, displayFull, meta.Agent)
		} else if verbose && len(displayScoped) > 0 {
			displayScoped = maybeCompactExternalTranscript(ctx, displayScoped, meta.Agent)
		}
	outputExplainContent(w, output, noPager)

	// Printed to stderr so the note never lands in piped/paged stdout. The
	// signal reflects the raw scan budget, not the (filtered, grouped) display
	// count — so the wording stays vague ("may be hidden", no count) and names
	// the full `checkpoint explain` command, which works regardless of whether
	// the user reached this path via `explain`, `checkpoint explain`, or
	// `checkpoint list` (the latter two share this code but expose different
	// flags).
	if truncated {
		fmt.Fprint(errW, "note: checkpoint list reached its scan limit; older checkpoints may be hidden. "+
			"Run 'entire checkpoint explain --json --limit <N>' to see more.\n")
	}
	return nil
}

// outputExplainContent outputs content with optional pager support.
func outputExplainContent(w io.Writer, content string, noPager bool) {
	if noPager {
		fmt.Fprint(w, content)
	} else {
		outputWithPager(w, content)
	}
}

// runExplainCommit looks up the checkpoint associated with a commit.
// Extracts the Entire-Checkpoint trailer and delegates to checkpoint detail view.
// If no trailer found, shows a message indicating no associated checkpoint.
func runExplainCommit(ctx context.Context, w, errW io.Writer, commitRef string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}
	defer repo.Close()

	// Resolve the commit reference, erroring on hex-prefix ambiguity
	// instead of silently picking the first matching commit.
	hash, ambiguousMatches, err := resolveCommitUnambiguous(repo, commitRef)
	if err != nil {
		if errors.Is(err, errAmbiguousCommitPrefix) {
			renderAmbiguousPrefixFailure(errW, commitRef, "commits", buildAmbiguousCommitMatches(repo, ambiguousMatches))
			return NewSilentError(err)
		}
		return renderExplainFailure(errW, "Commit not found", []explainRow{
			{Label: "ref", Value: commitRef},
		}, fmt.Errorf("commit not found: %s", commitRef))
	}

	commit, err := repo.CommitObject(hash)
		if sig == os.Interrupt {
			fmt.Fprintln(os.Stderr, "\nInterrupting… press Ctrl-C again to force quit.")
		} else {
			fmt.Fprintln(os.Stderr, "\nReceived termination signal, shutting down… signal again to force quit.")
		}
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()

	// Create and execute root command
	rootCmd := cli.NewRootCmd()

	// Make managed-installed plugins discoverable by the kubectl-style
	// dispatcher: prepend the managed bin dir to PATH before resolution.
	// Idempotent and silent on failure (managed installs simply won't be
	// found this run; PATH-installed plugins still work). The closure
	// restores PATH so built-in commands and their subprocesses don't
	// inherit the prepended dir. When a plugin runs, we skip the restore
	// — the os.Exit ends the process, and the plugin child intentionally
	// inherits the prepended PATH so it can spawn sibling managed plugins.
	restorePATH := cli.PrependPluginBinDirToPATH(ctx)

	if handled, code := cli.MaybeRunPlugin(ctx, rootCmd, os.Args[1:]); handled {
		cancel()
		os.Exit(code)
	}
	restorePATH()

	// Retired env vars fail every built-in command up front; a removed knob
	// must never be silently ignored. Plugins (above) are exempt — what they
	// read is their business.
	if err := api.RejectRemovedAuthEnv(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		cancel()
		os.Exit(1)
	}

	executed, err := rootCmd.ExecuteContextC(ctx)
	// The only place the logger is closed, and it must be here: cobra returns out
	// of Command.execute() as soon as RunE errors or required-flag validation
		}
		return filepath.Join(v, pluginManagedTopDir, pluginManagedSubDir), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolve home dir: %w", err)
	}
	return filepath.Join(home, ".local", "share", pluginManagedTopDir, pluginManagedSubDir), nil
}

// PluginBinDir returns the managed install directory. Binaries (or symlinks)
// placed here are auto-discovered by the kubectl-style dispatcher because
// main.go prepends this dir to PATH before MaybeRunPlugin runs.
func PluginBinDir() (string, error) {
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedBinSubdir), nil
}

// PluginDataDir returns the per-plugin data directory for the given bare name
// (e.g. "pgr" for `entire-pgr`). The returned path is not created — that's
// the plugin's responsibility on first use.
//
// Returns an error for names the dispatcher would never invoke (empty,
// flag-shaped, agent-protocol-reserved, "."/".." path-traversal, slashes).
// This guarantees ENTIRE_PLUGIN_DATA_DIR always points inside the managed
// data subtree.
func PluginDataDir(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedDataSubdir, name), nil
}

